(int, int)? PairWithSum(int[] a, int target)
{
    int l = 0, r = a.Length - 1;
    while (l < r)
    {
        int sum = a[l] + a[r];
        if (sum == target) return (l, r);
        if (sum < target) l++;
        else r--;
    }
    return null;
}

int LongestUnique(string s)
{
    var last = new Dictionary<char, int>();
    int best = 0, left = 0;
    for (int right = 0; right < s.Length; right++)
    {
        if (last.TryGetValue(s[right], out int prev) && prev >= left)
            left = prev + 1;
        last[s[right]] = right;
        best = Math.Max(best, right - left + 1);
    }
    return best;
}

int SubarraySum(int[] nums, int k)
{
    var count = new Dictionary<int, int> { [0] = 1 };   // pusty prefiks
    int prefix = 0, result = 0;
    foreach (var x in nums)
    {
        prefix += x;
        result += count.GetValueOrDefault(prefix - k);
        count[prefix] = count.GetValueOrDefault(prefix) + 1;
    }
    return result;
}

int MaxSubArray(int[] nums)
{
    int best = nums[0], cur = nums[0];
    for (int i = 1; i < nums.Length; i++)
    {
        cur = Math.Max(nums[i], cur + nums[i]);
        best = Math.Max(best, cur);
    }
    return best;
}

int[] TwoSum(int[] nums, int target)
{
    var seen = new Dictionary<int, int>();   // wartość -> indeks
    for (int i = 0; i < nums.Length; i++)
    {
        if (seen.TryGetValue(target - nums[i], out int j))
            return [j, i];
        seen[nums[i]] = i;
    }
    return [];
}

