int[] TopK(int[] nums, int k)
{
    var freq = new Dictionary<int, int>();
    foreach (var x in nums) freq[x] = freq.GetValueOrDefault(x) + 1;

    var heap = new PriorityQueue<int, int>();   // min-heap po częstości
    foreach (var (value, count) in freq)
    {
        heap.Enqueue(value, count);
        if (heap.Count > k) heap.Dequeue();      // wyrzuć najrzadszy
    }
    return heap.UnorderedItems.Select(x => x.Element).ToArray();
}

bool IsValid(string s)
{
    var pairs = new Dictionary<char, char> { [')'] = '(', [']'] = '[', ['}'] = '{' };
    var stack = new Stack<char>();
    foreach (var c in s)
    {
        if (pairs.TryGetValue(c, out var open))
        {
            if (!stack.TryPop(out var top) || top != open) return false;
        }
        else if (c is '(' or '[' or '{') stack.Push(c);
    }
    return stack.Count == 0;
}

int[] DailyTemperatures(int[] t)
{
    var result = new int[t.Length];
    var stack = new Stack<int>();              // indeksy, temperatury malejąco
    for (int i = 0; i < t.Length; i++)
    {
        while (stack.Count > 0 && t[stack.Peek()] < t[i])
        {
            int j = stack.Pop();
            result[j] = i - j;
        }
        stack.Push(i);
    }
    return result;
}

