int ShortestPath(char[][] grid, (int r, int c) start, (int r, int c) end)
{
    int rows = grid.Length, cols = grid[0].Length;
    var dist = new Dictionary<(int, int), int> { [start] = 0 };
    var queue = new Queue<(int r, int c)>([start]);
    (int dr, int dc)[] dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)];
    while (queue.TryDequeue(out var cur))
    {
        if (cur == end) return dist[cur];
        foreach (var (dr, dc) in dirs)
        {
            var next = (r: cur.r + dr, c: cur.c + dc);
            if (next.r < 0 || next.r >= rows || next.c < 0 || next.c >= cols) continue;
            if (grid[next.r][next.c] == '#' || dist.ContainsKey(next)) continue;
            dist[next] = dist[cur] + 1;
            queue.Enqueue(next);
        }
    }
    return -1;
}

int NumIslands(char[][] grid)
{
    int count = 0;
    for (int r = 0; r < grid.Length; r++)
        for (int c = 0; c < grid[0].Length; c++)
            if (grid[r][c] == '1') { count++; Sink(grid, r, c); }
    return count;
}

void Sink(char[][] g, int r, int c)
{
    if (r < 0 || c < 0 || r >= g.Length || c >= g[0].Length || g[r][c] != '1') return;
    g[r][c] = '0';                                  // oznacz jako odwiedzone
    Sink(g, r + 1, c); Sink(g, r - 1, c); Sink(g, r, c + 1); Sink(g, r, c - 1);
}

List<int>? TopoSort(int n, (int from, int to)[] edges)
{
    var graph = Enumerable.Range(0, n).Select(_ => new List<int>()).ToArray();
    var inDegree = new int[n];
    foreach (var (from, to) in edges) { graph[from].Add(to); inDegree[to]++; }

    var queue = new Queue<int>(Enumerable.Range(0, n).Where(v => inDegree[v] == 0));
    var order = new List<int>(n);
    while (queue.TryDequeue(out var v))
    {
        order.Add(v);
        foreach (var next in graph[v])
            if (--inDegree[next] == 0) queue.Enqueue(next);
    }
    return order.Count == n ? order : null;    // null = cykl
}

int[] Dijkstra(List<(int to, int w)>[] graph, int source)
{
    var dist = Enumerable.Repeat(int.MaxValue, graph.Length).ToArray();
    dist[source] = 0;
    var pq = new PriorityQueue<int, int>();
    pq.Enqueue(source, 0);
    while (pq.TryDequeue(out var u, out var d))
    {
        if (d > dist[u]) continue;              // przestarzały wpis (lazy deletion)
        foreach (var (v, w) in graph[u])
            if (d + w < dist[v])
            {
                dist[v] = d + w;
                pq.Enqueue(v, dist[v]);
            }
    }
    return dist;
}

long Power(long x, int n)              // x^n dla n >= 0, O(log n)
{
    if (n == 0) return 1;              // warunek bazowy
    long half = Power(x, n / 2);       // problem o połowę mniejszy
    return n % 2 == 0 ? half * half : half * half * x;
}

List<List<int>> Subsets(int[] nums)
{
    var result = new List<List<int>>();
    var current = new List<int>();
    void Backtrack(int start)
    {
        result.Add([.. current]);                  // kopia!
        for (int i = start; i < nums.Length; i++)
        {
            current.Add(nums[i]);                  // wybierz
            Backtrack(i + 1);                      // eksploruj
            current.RemoveAt(current.Count - 1);   // cofnij
        }
    }
    Backtrack(0);
    return result;
}

long Fib(int n, Dictionary<int, long>? memo = null)   // top-down: O(n) / O(n)
{
    if (n <= 1) return n;
    memo ??= new();
    if (memo.TryGetValue(n, out var cached)) return cached;
    return memo[n] = Fib(n - 1, memo) + Fib(n - 2, memo);
}

