int CoinChange(int[] coins, int amount)
{
    var dp = new int[amount + 1];                // dp[x] = min monet na kwotę x
    Array.Fill(dp, int.MaxValue);
    dp[0] = 0;
    for (int x = 1; x <= amount; x++)
        foreach (var c in coins)
            if (c <= x && dp[x - c] != int.MaxValue)
                dp[x] = Math.Min(dp[x], dp[x - c] + 1);
    return dp[amount] == int.MaxValue ? -1 : dp[amount];
}

int LengthOfLis(int[] nums)
{
    var tails = new List<int>();   // tails[k] = najmniejszy koniec podciągu długości k+1
    foreach (var x in nums)
    {
        int i = tails.BinarySearch(x);
        if (i < 0) i = ~i;         // indeks wstawienia
        if (i == tails.Count) tails.Add(x);
        else tails[i] = x;
    }
    return tails.Count;
}

int[] MergeSort(int[] a)
{
    if (a.Length <= 1) return a;
    int mid = a.Length / 2;
    var left = MergeSort(a[..mid]);
    var right = MergeSort(a[mid..]);
    var result = new int[a.Length];
    int i = 0, j = 0, k = 0;
    while (i < left.Length && j < right.Length)
        result[k++] = left[i] <= right[j] ? left[i++] : right[j++];  // <= = stabilność
    while (i < left.Length) result[k++] = left[i++];
    while (j < right.Length) result[k++] = right[j++];
    return result;
}

