int BinarySearch(int[] a, int target)
{
    int lo = 0, hi = a.Length - 1;
    while (lo <= hi)
    {
        int mid = lo + (hi - lo) / 2;      // zamiast (lo + hi) / 2 – brak overflow
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int LowerBound(int[] a, int target)     // pierwszy i, gdzie a[i] >= target
{
    int lo = 0, hi = a.Length;           // przedział półotwarty [lo, hi)
    while (lo < hi)
    {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;                           // a.Length, jeśli wszystkie < target
}
