int ShipWithinDays(int[] weights, int days)
{
    int lo = weights.Max(), hi = weights.Sum();
    while (lo < hi)
    {
        int cap = lo + (hi - lo) / 2;
        if (CanShip(weights, days, cap)) hi = cap; else lo = cap + 1;
    }
    return lo;
}

bool CanShip(int[] w, int days, int cap)
{
    int used = 1, load = 0;
    foreach (var x in w)
        if ((load += x) > cap) { used++; load = x; }   // nowy dzień
    return used <= days;
}

