public class LruCache<TKey, TValue>(int capacity) where TKey : notnull
{
    private readonly Dictionary<TKey, LinkedListNode<(TKey Key, TValue Value)>> _map = new();
    private readonly LinkedList<(TKey Key, TValue Value)> _list = new();  // first = najświeższy

    public bool TryGet(TKey key, out TValue value)
    {
        if (!_map.TryGetValue(key, out var node)) { value = default!; return false; }
        _list.Remove(node); _list.AddFirst(node);
        value = node.Value.Value;
        return true;
    }

    public void Put(TKey key, TValue value)
    {
        if (_map.TryGetValue(key, out var node)) _list.Remove(node);
        else if (_map.Count == capacity) { _map.Remove(_list.Last!.Value.Key); _list.RemoveLast(); }
        _map[key] = _list.AddFirst((key, value));
    }
}

public class SlidingWindowLimiter(int limit, TimeSpan window, TimeProvider clock)
{
    private readonly Dictionary<string, Queue<DateTimeOffset>> _hits = new();
    private readonly Lock _lock = new();                       // .NET 9

    public bool TryAcquire(string clientId)
    {
        lock (_lock)
        {
            var now = clock.GetUtcNow();
            if (!_hits.TryGetValue(clientId, out var q)) _hits[clientId] = q = new();
            while (q.Count > 0 && now - q.Peek() >= window) q.Dequeue();
            if (q.Count >= limit) return false;
            q.Enqueue(now);
            return true;
        }
    }
}

string Decode(string s)
{
    var counts = new Stack<int>();
    var parts = new Stack<StringBuilder>();
    var current = new StringBuilder();
    int k = 0;
    foreach (var c in s)
    {
        if (char.IsAsciiDigit(c)) k = k * 10 + (c - '0');
        else if (c == '[') { counts.Push(k); parts.Push(current); current = new(); k = 0; }
        else if (c == ']')
        {
            var prev = parts.Pop();                                   // dopisz bieżący × k
            current = prev.Insert(prev.Length, current.ToString(), counts.Pop());
        }
        else current.Append(c);
    }
    return current.ToString();
}

