int[][] Merge(int[][] intervals)
{
    var result = new List<int[]>();
    foreach (var cur in intervals.OrderBy(i => i[0]))
    {
        if (result.Count > 0 && cur[0] <= result[^1][1])
            result[^1][1] = Math.Max(result[^1][1], cur[1]);
        else
            result.Add([cur[0], cur[1]]);   // kopia – nie modyfikuję wejścia
    }
    return result.ToArray();
}

